insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_139'
from (values
('127.888.d.15.A',3,'A student checks cylinder pressure, tests the regulator and flow indicator, and checks lines for leaks on a trainer''s oxygen system. She is:','["inspecting and servicing an oxygen system", "ignoring the system", "venting the cylinder", "painting the cylinder"]'::jsonb,0,'Oxygen service.','original'),
('127.888.d.15.A',4,'Oxygen system servicing should be done in an area that is:','["full of grease", "well ventilated and free of oil and flame", "next to fuel", "closed and hot"]'::jsonb,1,'Oxygen area.','original'),
('127.888.d.15.B',3,'A mechanic wipes an emergency mask with approved cleaner and checks the hose for cracks and the bag for holes. She is:','["tossing the masks", "ignoring masks", "cleaning and inspecting emergency oxygen masks and supply hoses", "painting masks"]'::jsonb,2,'Mask care.','original'),
('127.888.d.15.B',4,'A cracked oxygen hose should be:','["taped", "painted", "ignored", "replaced"]'::jsonb,3,'Replace cracked hose.','original'),
('127.888.d.15.C',3,'A technician checks a cylinder''s hydrostatic test date, dents and corrosion before refilling it. She is:','["inspecting an oxygen system cylinder for serviceability", "skipping the date", "ignoring dents", "only painting it"]'::jsonb,0,'Cylinder check.','original'),
('127.888.d.15.C',4,'An oxygen cylinder past its hydrostatic test date should be:','["painted", "retested before it is refilled", "discarded in a trash can", "refilled anyway"]'::jsonb,1,'Hydro date.','original'),
('127.888.d.15.D',3,'A combustion heater won''t ignite, so the mechanic finds the troubleshooting chart in the manual. She is:','["replacing the cabin", "guessing the cause", "locating and describing the procedures to troubleshoot a combustion heater", "ignoring the heater"]'::jsonb,2,'Heater troubleshooting.','original'),
('127.888.d.15.D',4,'A heater that fails to ignite may have a fault in the:','["tire pressure", "paint finish", "seat belt", "spark source or fuel supply"]'::jsonb,3,'Heater faults.','original'),
('127.888.d.15.E',3,'A technician follows the manual''s steps to evacuate, charge and leak-test the air conditioning system. She is:','["locating and describing the procedures for servicing a refrigerant (vapor-cycle) system", "guessing the charge", "venting refrigerant", "skipping steps"]'::jsonb,0,'Refrigerant service.','original'),
('127.888.d.15.E',4,'Before charging a vapor-cycle system, technicians evacuate it to remove:','["fuel", "air and moisture", "oil", "refrigerant"]'::jsonb,1,'Evacuate first.','original'),
('127.888.d.15.F',3,'A cabin cooling turbine runs warm, so the mechanic looks up the troubleshooting steps for an air-cycle unit. She is:','["guessing", "ignoring the unit", "locating and describing troubleshooting procedures for an air-cycle system", "replacing the seats"]'::jsonb,2,'Air-cycle faults.','original'),
('127.888.d.15.F',4,'A clogged inlet screen on an air-cycle machine will most likely cause:','["extra cooling", "more lift", "a quieter cabin", "poor cooling output"]'::jsonb,3,'Clogged screen.','original'),
('127.888.d.15.G',3,'A mechanic pressure-tests an exhaust muff and checks the shroud for cracks and holes. She is:','["inspecting a cabin heater system with an exhaust heat exchanger for cracks", "ignoring the heater", "cleaning the seats", "painting the muff"]'::jsonb,0,'Muff inspection.','original'),
('127.888.d.15.G',4,'A crack in the exhaust shroud is serious because it can:','["cool the engine", "leak carbon monoxide into the cabin air", "add lift", "improve heat"]'::jsonb,1,'CO leak.','original'),
('127.888.d.15.H',3,'A pilot reports the cabin won''t hold pressure, so the mechanic opens the pressurization troubleshooting chart. She is:','["guessing the cause", "painting the door", "locating troubleshooting procedures for a pressurization system", "ignoring the report"]'::jsonb,2,'Pressurization faults.','original'),
('127.888.d.15.H',4,'A common cause of a cabin that cannot hold pressure is a:','["full ashtray", "bright light", "new carpet", "worn door seal or leaking valve"]'::jsonb,3,'Seal leaks.','original'),
('127.888.d.16.A',3,'A student studies the red, amber and green lights on a panel and what each means. She is:','["describing annunciator systems and the meaning of warning, caution and advisory", "describing fuel", "describing seats", "describing tires"]'::jsonb,0,'Annunciators.','original'),
('127.888.d.16.A',4,'A red annunciator light normally indicates:','["all is well", "a warning that needs immediate attention", "a caution only", "an advisory"]'::jsonb,1,'Red means warning.','original'),
('127.888.d.16.B',3,'A student compares a float-type fuel gauge with a capacitance probe system. She is:','["comparing seats", "comparing tires", "differentiating between fuel quantity indicating systems", "comparing paint"]'::jsonb,2,'Fuel quantity.','original'),
('127.888.d.16.B',4,'A capacitance-type fuel gauge measures fuel quantity by sensing:','["cabin noise", "tire pressure", "paint thickness", "the changing electrical capacitance as fuel level changes"]'::jsonb,3,'Capacitance probe.','original'),
('127.888.d.16.C',3,'A mechanic sorts the attitude indicator, heading indicator and turn coordinator by how they are driven. She is:','["differentiating between types of gyroscopic instruments", "sorting wheels", "sorting seats", "sorting lights"]'::jsonb,0,'Gyro instruments.','original'),
('127.888.d.16.C',4,'A vacuum-driven gyro instrument spins its gyro using:','["fuel flow", "air flowing through the instrument case", "a battery only", "a tire"]'::jsonb,1,'Vacuum gyro.','original'),
('127.888.d.16.D.i',3,'A technician compensates a magnetic compass on a compass rose and records the corrections on a card. She is:','["painting the compass", "ignoring the card", "explaining the function and operation of magnetic compasses and compass swinging", "avoiding compasses"]'::jsonb,2,'Compass swing.','original'),
('127.888.d.16.D.i',4,'A compass is swung to reduce errors caused by:','["tire wear", "paint color", "fuel type", "magnetic fields from the aircraft itself"]'::jsonb,3,'Deviation.','original'),
('127.888.d.16.D.ii',3,'A mechanic studies how a Bourdon tube reads oil pressure and a thermocouple reads cylinder head temperature. She is:','["explaining pressure and temperature indicating instruments", "avoiding gauges", "ignoring gauges", "painting gauges"]'::jsonb,0,'P and T gauges.','original'),
('127.888.d.16.D.ii',4,'A Bourdon tube indicator works because the tube:','["burns", "tends to straighten as internal pressure increases", "melts", "freezes"]'::jsonb,1,'Bourdon tube.','original'),
('127.888.d.16.D.iii',3,'A student traces how a synchro sensor on a flap sends its position to a cockpit indicator. She is:','["avoiding sensors", "ignoring flaps", "explaining position indication sensors and instruments", "painting sensors"]'::jsonb,2,'Position sensors.','original'),
('127.888.d.16.D.iii',4,'A position sensor on a control surface sends a signal that is:','["burned", "cooled", "ignored", "shown on a cockpit indicator"]'::jsonb,3,'Position signal.','original'),
('127.888.d.16.D.iv',3,'A student reads about a system that shows engine data on a screen and alerts the crew to exceedances. She is:','["explaining engine indication and crew alerting systems", "describing tires", "avoiding engines", "describing seats"]'::jsonb,0,'EICAS.','original'),
('127.888.d.16.D.iv',4,'An engine indication and crew alerting system helps the crew by:','["cooling the engine", "showing engine data and warning of abnormal conditions", "hiding data", "steering the plane"]'::jsonb,1,'Crew alerting.','original'),
('127.888.d.16.D.v',3,'A mechanic checks the engine-driven vacuum pump, regulator and filter on a vacuum instrument system. She is:','["painting the pump", "avoiding vacuum", "explaining instrument vacuum and pneumatic systems", "ignoring the pump"]'::jsonb,2,'Vacuum system.','original'),
('127.888.d.16.D.v',4,'A vacuum regulator keeps the system at:','["maximum suction", "random suction", "zero suction", "the correct, steady suction level for the gyros"]'::jsonb,3,'Vacuum regulation.','original'),
('127.888.d.16.D.vi',3,'A technician follows air from the pitot tube and static ports to the altimeter, airspeed indicator and vertical speed indicator. She is:','["explaining pitot-static systems", "ignoring the ports", "avoiding the systems", "painting the tube"]'::jsonb,0,'Pitot-static.','original'),
('127.888.d.16.D.vi',4,'A blocked pitot tube would most directly affect the:','["compass", "airspeed indicator", "clock", "fuel gauge"]'::jsonb,1,'Pitot blockage.','original'),
('127.888.d.16.D.vii',3,'A student studies a glass cockpit with a primary flight display and a multi-function display. She is:','["describing seats", "describing steam gauges only", "explaining electronic displays and flight instrument systems", "describing tires"]'::jsonb,2,'Glass cockpit.','original'),
('127.888.d.16.D.vii',4,'A primary flight display typically combines the:','["tires and brakes", "fuel and seats", "radios only", "attitude, airspeed, altitude and heading data on one screen"]'::jsonb,3,'PFD.','original'),
('127.888.d.16.D.viii',3,'A student studies how the transponder replies with a code and how the encoder sends altitude data. She is:','["explaining transponder and encoder systems", "painting antennas", "avoiding transponders", "ignoring codes"]'::jsonb,0,'Transponder.','original'),
('127.888.d.16.D.viii',4,'A Mode C transponder reply includes the aircraft''s:','["tire pressure", "pressure altitude", "fuel load", "cabin temperature"]'::jsonb,1,'Mode C.','original'),
('127.888.d.16.D.ix',3,'A mechanic studies how a vane or probe senses airflow angle and triggers a stall horn. She is:','["ignoring horns", "avoiding vanes", "explaining angle of attack and stall warning systems", "painting probes"]'::jsonb,2,'AOA sensor.','original'),
('127.888.d.16.D.ix',4,'A stall warning system alerts the pilot that the wing is:','["climbing normally", "adding fuel", "cooling", "approaching a stall"]'::jsonb,3,'Stall warning.','original'),
('127.888.d.16.D.x',3,'A student studies how a horn warns when the throttle is closed with the gear up. She is:','["explaining takeoff and landing gear configuration warning systems", "painting gear", "avoiding horns", "ignoring switches"]'::jsonb,0,'Configuration warning.','original'),
('127.888.d.16.D.x',4,'A takeoff configuration warning sounds if the aircraft is:','["cold", "not set up properly for takeoff, such as with flaps wrong", "at rest", "parked"]'::jsonb,1,'Takeoff warning.','original'),
('127.888.d.17.A',3,'A mechanic labels and disconnects lines, removes the mounting screws and slides out an old gauge, then installs a new one. She is:','["painting an instrument", "buying an instrument", "removing and installing an aircraft instrument", "ignoring an instrument"]'::jsonb,2,'Instrument R&I.','original'),
('127.888.d.17.A',4,'When removing an instrument, lines should be capped to prevent:','["paint contact", "extra lift", "too much pressure", "dirt and moisture from entering the system"]'::jsonb,3,'Cap lines.','original'),
('127.888.d.17.B',3,'A mechanic sets the altimeter''s Kollsman window until it reads field elevation and then reads the barometric setting. She is:','["determining barometric pressure using an altimeter", "ignoring the window", "guessing pressure", "using a ruler"]'::jsonb,0,'Barometric setting.','original'),
('127.888.d.17.B',4,'An altimeter''s Kollsman window shows:','["the cabin temperature", "the local barometric pressure setting", "the fuel flow", "the compass heading"]'::jsonb,1,'Kollsman.','original'),
('127.888.d.17.C',3,'A mechanic checks the green, yellow and red arcs on an airspeed indicator against the aircraft''s limits. She is:','["guessing markings", "ignoring arcs", "verifying proper range markings on an instrument for a particular aircraft", "painting the glass"]'::jsonb,2,'Range markings.','original'),
('127.888.d.17.C',4,'The yellow arc on an airspeed indicator warns the pilot of:','["never-exceed speed", "slowest flight", "normal operating range", "the caution range, for smooth air only"]'::jsonb,3,'Yellow arc.','original'),
('127.888.d.17.D',3,'A gyro instrument reads low, so the mechanic opens the manual to the vacuum system troubleshooting chart. She is:','["locating the procedures for troubleshooting a vacuum-operated instrument system", "guessing", "ignoring the gyro", "painting the case"]'::jsonb,0,'Vacuum troubleshooting.','original'),
('127.888.d.17.D',4,'A common cause of low vacuum is a:','["new seat", "clogged filter or worn pump", "clean filter", "bright paint"]'::jsonb,1,'Low vacuum.','original'),
('127.888.d.17.E',3,'A student labels the probe, wiring and gauge of an EGT system on a diagram. She is:','["identifying lights", "identifying seats", "identifying exhaust gas temperature system components", "identifying tires"]'::jsonb,2,'EGT parts.','original'),
('127.888.d.17.E',4,'An EGT probe is usually a:','["fuel pump", "pitot tube", "tire valve", "thermocouple placed in the exhaust"]'::jsonb,3,'EGT thermocouple.','original'),
('127.888.d.17.F',3,'A mechanic opens the alternate static source valve and checks that the instruments respond correctly. She is:','["inspecting an aircraft''s alternate static air source", "painting the valve", "ignoring the source", "closing the system"]'::jsonb,0,'Alternate static.','original'),
('127.888.d.17.F',4,'The alternate static source is used if the:','["seat is loose", "normal static port becomes blocked", "engine is cold", "battery is new"]'::jsonb,1,'Alternate use.','original'),
('127.888.d.17.G',3,'A mechanic looks up how to set the stall warning vane so the horn sounds just above stall. She is:','["guessing", "painting the vane", "locating and explaining the adjustment procedures for a stall warning system", "ignoring the horn"]'::jsonb,2,'Stall warning adjust.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_139'
from (values
('127.888.d.17.G',4,'A stall warning should sound at a speed:','["after the stall", "at cruise", "below the stall", "a few knots above the actual stall"]'::jsonb,3,'Adjust above stall.','original'),
('127.888.d.18.A',3,'A student draws a transmitter, receiver, antenna and microphone to explain a radio. She is:','["describing radio operating principles and radio components", "avoiding radios", "describing tires", "describing seats"]'::jsonb,0,'Radio basics.','original'),
('127.888.d.18.A',4,'An antenna in a radio system:','["stores fuel", "radiates and receives radio waves", "cools the radio", "holds the wings"]'::jsonb,1,'Antenna.','original'),
('127.888.d.18.B',3,'A mechanic bonds an antenna to the skin and fits static wicks on the trailing edges. She is:','["avoiding mounts", "painting antennas", "identifying and explaining mounting requirements of antennas and static discharge wicks", "ignoring wicks"]'::jsonb,2,'Mounting.','original'),
('127.888.d.18.B',4,'Static discharge wicks help by:','["adding static", "adding noise", "adding lift", "bleeding off static electricity from the aircraft"]'::jsonb,3,'Static wicks.','original'),
('127.888.d.18.C',3,'A student labels VHF, HF and satellite antennas and radios on an airliner diagram. She is:','["identifying the components of communication systems", "labeling lights", "labeling tires", "labeling seats"]'::jsonb,0,'Comm components.','original'),
