('127.888.d.18.H',4,'A radio altimeter measures:','["airspeed", "fuel level", "cabin pressure", "height above the ground"]'::jsonb,3,'Radio altimeter.','original'),
('127.888.d.18.I',3,'A student explains how TCAS warns of nearby traffic and ADS-B broadcasts position. She is:','["explaining the basic operation of collision avoidance systems", "avoiding traffic", "describing seats", "describing tires"]'::jsonb,0,'Collision operation.','original'),
('127.888.d.18.I',4,'An ADS-B Out system:','["cools the engine", "broadcasts the aircraft''s position to others", "listens only", "steers the aircraft"]'::jsonb,1,'ADS-B.','original'),
('127.888.d.18.J',3,'A student traces the headset jacks, audio panel and amplifier of a crew intercom. She is:','["describing tires", "describing seats", "identifying the components and explaining the basic operation of intercom systems", "avoiding intercoms"]'::jsonb,2,'Intercom.','original'),
('127.888.d.18.J',4,'An intercom lets crew members:','["silence the radio only", "avoid hearing", "lose audio", "talk to each other without using the radio"]'::jsonb,3,'Intercom purpose.','original'),
('127.888.d.18.K',3,'A student explains how a radar antenna sends pulses and displays the returns from storm cells. She is:','["identifying the components and explaining the basic operation of weather radar", "describing tires", "describing seats", "avoiding radar"]'::jsonb,0,'Weather radar.','original'),
